type Kind = 'document' | 'transaction' | 'actor' | 'timestamp' | 'url';
type Issue = { code: string; message: string; path?: string; hint?: string };
type Case = { kind: Kind; input: unknown; expect: { ok: true; value: unknown } | { ok: false; issues: Issue[] } };
const cases: Case[] = [];
const seen = new Map<string, number>();
const CAP_PER_FAILURE = 4, CAP_VALID_MUTATIONS = 60;
let validMutations = 0;

function verdict(kind: Kind, input: unknown): Case['expect'] {
  switch (kind) {
    case 'document': return validateDocument(input) as Case['expect'];
    case 'transaction': return validateTransaction(input) as Case['expect'];
    case 'actor': try { return { ok: true, value: readActor(input) }; } catch (e) { return { ok: false, issues: [(e as { issue: Issue }).issue] }; }
    case 'timestamp': try { return { ok: true, value: timestamp(input) }; } catch (e) { return { ok: false, issues: [(e as { issue: Issue }).issue] }; }
    case 'url': { const href = safeUrl(input); return href === null ? { ok: false, issues: [] } : { ok: true, value: href }; }
  }
}
function add(kind: Kind, input: unknown, mutated = false): void {
  const json = JSON.stringify(input);
  const expect = verdict(kind, JSON.parse(json) as unknown);
  const normalized = JSON.parse(JSON.stringify(expect)) as Case['expect'];
  if (mutated) {
    const key = normalized.ok ? 'valid' : `${kind}:${normalized.issues[0]?.message}:${(normalized.issues[0]?.path ?? '').replace(/\d+/g, '#').replace(/\.(?:[a-z][\w-]*)$/i, '.*')}`;
    const count = seen.get(key) ?? 0;
    if (normalized.ok ? validMutations >= CAP_VALID_MUTATIONS : count >= CAP_PER_FAILURE) return;
    seen.set(key, count + 1);
    if (normalized.ok) validMutations++;
  }
  const entry: Case & { portRejects?: true } = { kind, input: JSON.parse(json) as unknown, expect: normalized };
  if (kind === 'url' && normalized.ok && urlUnsupported(input as string)) entry.portRejects = true;
  cases.push(entry);
}
/** Forms the Go and Python ports deliberately refuse although the reference accepts them (the safe direction). */
function urlUnsupported(url: string): boolean {
  const authority = url.replace(/^[A-Za-z]+:[/\\]*/, '').split(/[/?#]/)[0] ?? '';
  const host = (authority.includes('@') ? authority.slice(authority.lastIndexOf('@') + 1) : authority).replace(/:[0-9]*$/, '');
  if (authority.includes('@') && !/^:?@/.test(authority)) return true;
  if (host.startsWith('[') || /[^\x00-\x7f]/.test(decodeURIComponentSafe(host)) || /(^|\.)xn--/i.test(host)) return true;
  const labels = host.split('.');
  const last = (labels.length > 1 && labels[labels.length - 1] === '' ? labels[labels.length - 2] : labels[labels.length - 1]) ?? '';
  if (/^[0-9]+$/.test(last) || /^0x[0-9a-f]*$/i.test(last)) return !(labels.length === 4 && labels.every(l => /^(?:0|[1-9][0-9]{0,2})$/.test(l) && Number(l) <= 255));
  return false;
}
function decodeURIComponentSafe(value: string): string { try { return decodeURIComponent(value); } catch { return value; } }

